import { useEffect, useRef, useState } from 'react';
import { GoogleGenerativeAI } from '@google/generative-ai';
import akiliLogo from '../assets/appstorechat.png';

// Initialize Gemini API
const genAI = new GoogleGenerativeAI('AIzaSyAoEVxYdKfjAMDrhQjgE522xYLf621uk0w');
const model = genAI.getGenerativeModel({ model: 'gemini-pro' });

interface Message {
  sender: 'user' | 'bot';
  text: string;
}

const Chatbot = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);

  const chatEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  const toggleChat = () => setIsOpen(!isOpen);

  const sendMessage = async () => {
    if (!question.trim()) return;

    const userMessage: Message = { sender: 'user', text: question };
    setMessages((prev) => [...prev, userMessage]);
    setQuestion('');
    setLoading(true);

    try {
      const result = await model.generateContent({
        contents: [
          {
            role: 'user',
            parts: [
              {
                text: `
You are Akili, an AI assistant representing Akiliedge Solution, a Kenyan company dedicated to 'Building Sustainable Solutions' and 'Empowering African communities through tech solutions.' Our focus areas include:
- Software development
- IoT systems
- product design
- AI solutions
- Community empowerment through technology
Our email is steve.devakiliedge@gmail.com
Phone number is +254703373810

Please answer in a friendly, professional, and confident tone, reflecting our values. Offer partnerships and mention our contact info if relevant. User's question: ${question}
              `,
              },
            ],
          },
        ],
      });

      const botMessage: Message = { sender: 'bot', text: result.response.text() };
      setMessages((prev) => [...prev, botMessage]);
    } catch (error) {
      console.error(error);
      setMessages((prev) => [
        ...prev,
        { sender: 'bot', text: 'Oops! Something went wrong. Please try again later.' },
      ]);
    }

    setLoading(false);
  };

  return (
    <div>
      {/* Floating Chat Icon */}
      <button
        className="fixed bottom-6 right-6 bg-[#972326] text-white p-4 rounded-full shadow-lg hover:bg-primary-dark transition-transform transform hover:scale-110 z-[9999]"
        onClick={toggleChat}
      >
        💬
      </button>

      {/* Chat Popup */}
      {isOpen && (
        <div className="fixed bottom-20 right-4 left-4 sm:right-6 sm:left-auto bg-white w-auto sm:w-96 h-[32rem] rounded-lg shadow-lg border flex flex-col z-[9999]">
          {/* Header */}
          <div className="bg-[#fed90f] text-black p-3 flex justify-between items-center font-bold rounded-t-lg">
            <div className="flex items-center gap-2">
              <img src={akiliLogo} alt="Akiliedge Logo" className="h-10 w-10 rounded-full object-cover" />
              <span>Chat with Akili</span>
            </div>
            <button onClick={toggleChat} className="text-black text-2xl">&times;</button>
          </div>

          {/* Chat Messages */}
          <div className="flex-1 p-3 overflow-y-auto space-y-3 bg-gray-50">
            {messages.map((msg, index) => (
              <div
                key={index}
                className={`p-3 rounded-lg max-w-[95%] break-words ${
                  msg.sender === 'user' ? 'bg-blue-100 self-end ml-auto' : 'bg-gray-200 self-start'
                }`}
              >
                {msg.text}
              </div>
            ))}
            {loading && (
              <div className="bg-gray-200 p-3 rounded-lg max-w-[95%] self-start">
                Akili is typing...
              </div>
            )}
            <div ref={chatEndRef}></div>
          </div>

          {/* Input Field */}
          <div className="p-3 border-t bg-white flex items-center gap-2">
            <input
              type="text"
              className="flex-grow border rounded p-2 focus:outline-none focus:ring-2 focus:ring-[#972326]"
              placeholder="Ask anything..."
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
            />
            <button
              className="bg-[#972326] text-white px-4 py-2 rounded-lg hover:bg-[#7d1c1f] disabled:opacity-50"
              onClick={sendMessage}
              disabled={loading}
            >
              Send
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Chatbot;
